const clientes = $input.first().json.body.clientes;

return clientes.map(cliente => ({
  json: cliente
}));

const clientes = $('Code in JavaScript').all().map(item => item.json);

const respostaCSV = $('HTTP Request1').first().json;
const csv = respostaCSV.data ?? respostaCSV.body;

if (typeof csv !== 'string') {
  throw new Error(
    'O HTTP Request1 não retornou o CSV como texto. Verifique a saída desse nó.'
  );
}

const linhas = csv.trim().split(/\r?\n/);
const cabecalhos = linhas.shift().split(',').map(c => c.trim());

const investimentos = linhas.map(linha => {
  const valores = linha.split(',').map(v => v.trim());
  return Object.fromEntries(
    cabecalhos.map((cabecalho, i) => [cabecalho, valores[i] ?? ''])
  );
});

return clientes.map(cliente => {
  const perfil = String(cliente.perfil ?? '').trim().toLowerCase();

  const investimento = investimentos.find(item =>
    String(item.perfil ?? '').trim().toLowerCase() === perfil
  );

  let mensagem;

  if (perfil === 'conservador') {
    mensagem = `Olá, ${cliente.nome}! Para seu perfil conservador, avalie opções com foco em segurança e previsibilidade.`;
  } else if (perfil === 'moderado') {
    mensagem = `Olá, ${cliente.nome}! Para seu perfil moderado, avalie uma estratégia equilibrada entre segurança e crescimento.`;
  } else if (perfil === 'arrojado') {
    mensagem = `Olá, ${cliente.nome}! Para seu perfil arrojado, avalie alternativas diversificadas, considerando os riscos envolvidos.`;
  } else {
    mensagem = `Olá, ${cliente.nome}! Vamos analisar seu perfil para personalizar sua mensagem.`;
  }

  return {
    json: {
      ...cliente,
      investimento_sugerido: investimento ?? null,
      mensagem
    }
  };
});
